# A custom container that gets Sequence behaviour almost for free
from collections.abc import Sequence

class Playlist(Sequence):
    def __init__(self, songs): self._songs = list(songs)
    def __getitem__(self, i): return self._songs[i]          # supports slicing too
    def __len__(self): return len(self._songs)

p = Playlist(["a", "b", "c"])
print(len(p), p[1], p[1:], "b" in p, list(reversed(p)), p.index("c"))   # contains/iter/index come from the ABC

# Callable object with state, and an LRU-ish cache decorator using the data model
class Counter:
    def __init__(self): self.n = 0
    def __call__(self): self.n += 1; return self.n
c = Counter(); c(); c()
print(c.n)   # 2

from functools import cache
@cache
def fib(n): return n if n < 2 else fib(n - 1) + fib(n - 2)
print(fib(80))

