# Lazy data pipeline + a typed, parameterised decorator
import functools, time
from typing import Callable, ParamSpec, TypeVar

P = ParamSpec("P")
R = TypeVar("R")

def retry(times: int = 3, delay: float = 0.05) -> Callable[[Callable[P, R]], Callable[P, R]]:
    def deco(fn: Callable[P, R]) -> Callable[P, R]:
        @functools.wraps(fn)
        def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
            for i in range(times):
                try:
                    return fn(*args, **kwargs)
                except Exception:
                    if i == times - 1:
                        raise
                    time.sleep(delay * 2 ** i)
            raise AssertionError("unreachable")
        return wrapper
    return deco

calls = {"n": 0}
@retry(times=3)
def flaky():
    calls["n"] += 1
    if calls["n"] < 3: raise ConnectionError("try again")
    return "ok"
print(flaky(), calls)        # ok {'n': 3}

# Batching generator: process a huge iterable in chunks with constant memory
def batched(iterable, n):
    it = iter(iterable)
    while chunk := list(islice(it, n)):
        yield chunk

from itertools import islice
print([sum(b) for b in batched(range(10), 4)])   # [6, 22, 17]
